const express = require('express');
const { Scalekit } = require('@scalekit-sdk/node');
const jwt = require('jsonwebtoken');

const app = express();
const port = 3001;

// Initialize Scalekit client
// Note: In a real application, these would come from environment variables
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL || 'https://your-env.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

app.get('/callback', async (req, res) => {
  const { code, state } = req.query;

  if (!code) {
    return res.status(400).json({ error: 'Missing authorization code' });
  }

  try {
    // Exchange the code for tokens
    const redirectUri = 'http://localhost:3001/callback';
    const tokens = await scalekit.authenticateWithCode(code, redirectUri);

    // Decode the idToken
    const decodedToken = jwt.decode(tokens.idToken);

    if (!decodedToken) {
      return res.status(500).json({ error: 'Failed to decode ID token' });
    }

    // Extract email and name
    const { email, name } = decodedToken;

    res.json({
      email,
      name
    });
  } catch (error) {
    console.error('Authentication error:', error);
    res.status(500).json({ error: 'Authentication failed', details: error.message });
  }
});

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});

